import{_ as e}from"./chunks/command-center.B7oOAUBI.js";import{_ as t,o as l,c as r,a2 as o}from"./chunks/framework.CWgsre3x.js";const _=JSON.parse('{"title":"Κέντρο επιχειρήσεων","description":"","frontmatter":{},"headers":[],"relativePath":"el/plus/command-center.md","filePath":"el/plus/command-center.md"}'),i={name:"el/plus/command-center.md"};function s(n,a,c,h,p,d){return l(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="κεντρο-επιχειρησεων" tabindex="-1">Κέντρο επιχειρήσεων <a class="header-anchor" href="#κεντρο-επιχειρησεων" aria-label="Permalink to &quot;Κέντρο επιχειρήσεων&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς</p><p>TransferBook+ v0.7.9: προσχέδιο ελεγμένο στον πηγαίο κώδικα. Η διαθεσιμότητα εξαρτάται από την εγκατεστημένη έκδοση, τα δικαιώματα και τις ρυθμίσεις· δεν επιβεβαιώνεται εμπορική ενεργοποίηση.</p></div><h2 id="εικονογραφημενη-προβολη" tabindex="-1">Εικονογραφημένη προβολή <a class="header-anchor" href="#εικονογραφημενη-προβολη" aria-label="Permalink to &quot;Εικονογραφημένη προβολή&quot;">​</a></h2><p><a href="/screenshots/v0.7.11/command-center.png"><img src="'+e+'" alt="Κέντρο επιχειρήσεων: εκκρεμείς προσφορές και αναθέσεις, ημερήσιοι δείκτες και συντομεύσεις."></a></p><p><em>Επιλέξτε την εικόνα για προβολή στο αρχικό της μέγεθος. Επιστρέψτε με το κουμπί Πίσω του προγράμματος περιήγησης.</em></p><p><em>Κέντρο επιχειρήσεων: εκκρεμείς προσφορές και αναθέσεις, ημερήσιοι δείκτες και συντομεύσεις.</em></p><p>Λήψη από περιβάλλον δοκιμών, TransferBook+ v0.7.11· αγγλικό περιβάλλον. Ενδεικτικά δοκιμαστικά στοιχεία. Η εικόνα δεν αποδεικνύει διαθεσιμότητα στην παραγωγή. Έχουν καλυφθεί αναγνωριστικά στοιχεία.</p><p>Χρησιμοποιήστε τον πίνακα για να εντοπίσετε εκκρεμότητες και να διακρίνετε την επιχειρησιακή απόδοση από τις εισπράξεις.</p><h2 id="πριν-ξεκινησετε" tabindex="-1">Πριν ξεκινήσετε <a class="header-anchor" href="#πριν-ξεκινησετε" aria-label="Permalink to &quot;Πριν ξεκινήσετε&quot;">​</a></h2><p>Χρησιμοποιήστε εγκεκριμένο περιβάλλον, επιβεβαιώστε εταιρεία και ρόλο και χρησιμοποιήστε συνθετικά στοιχεία για εκπαίδευση.</p><h2 id="διαδικασια" tabindex="-1">Διαδικασία <a class="header-anchor" href="#διαδικασια" aria-label="Permalink to &quot;Διαδικασία&quot;">​</a></h2><ol><li>Ελέγξτε τις ουρές εκκρεμοτήτων (Operational attention queues) και δώστε προτεραιότητα στις εξαιρέσεις.</li><li>Ελέγξτε τους βασικούς δείκτες (Operational key metrics). Η αξία κρατήσεων και οι εισπράξεις είναι διαφορετικά μεγέθη· μια επιβεβαιωμένη κράτηση δεν είναι απαραίτητα εξοφλημένη.</li><li>Εξετάστε τις επερχόμενες αφίξεις αεροδρομίων και λιμανιών, τη διαθεσιμότητα οδηγών και στόλου και το πρόσφατο ιστορικό κρατήσεων. Ανοίξτε τη σχετική κράτηση για ενέργειες.</li></ol><h2 id="επαληθευση-και-αντιμετωπιση-προβληματων" tabindex="-1">Επαλήθευση και αντιμετώπιση προβλημάτων <a class="header-anchor" href="#επαληθευση-και-αντιμετωπιση-προβληματων" aria-label="Permalink to &quot;Επαλήθευση και αντιμετώπιση προβλημάτων&quot;">​</a></h2><p>Αν μια ουρά ή ένας δείκτης είναι κενός, ελέγξτε εταιρεία, περιοχή, δικαιώματα και τρόπο λειτουργίας. Οι δείκτες δεν αποδεικνύουν ζωντανό GPS ή ολοκληρωμένη πληρωμή.</p><h2 id="σχετικοι-οδηγοι" tabindex="-1">Σχετικοί οδηγοί <a class="header-anchor" href="#σχετικοι-οδηγοι" aria-label="Permalink to &quot;Σχετικοί οδηγοί&quot;">​</a></h2><ul><li><a href="/el/plus/">Εγχειρίδιο χειριστή</a></li><li><a href="/el/plus/reservations.html">Κρατήσεις</a></li><li><a href="/el/plus/dispatch-schedule.html">Πρόγραμμα αναθέσεων</a></li></ul>',16)])])}const f=t(i,[["render",s]]);export{_ as __pageData,f as default};
